--- a/packages/workflow/src/expressions/native-evaluation/evaluator.ts
+++ b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
@@ -286,6 +286,27 @@ function flatSize(array: unknown[], depth: number): number {
  */
 const STRINGIFIES_ELEMENTS = new Set(['join', 'toSorted']);

+/**
+ * Array methods that compare their argument against every element. A string
+ * compared against a string element of the same length is compared by
+ * content, so one call over a few large strings is work proportional to
+ * their size, not to the element count.
+ */
+const COMPARES_ELEMENTS = new Set(['includes', 'indexOf', 'lastIndexOf']);
+
+/**
+ * Upper bound on the work of comparing an argument against every element:
+ * the length of each string element, one per other element. Elements are
+ * compared by reference past the top level, so nested content is not read.
+ */
+function comparisonWeight(receiver: unknown[]): number {
+	let weight = 0;
+	for (const element of receiver) {
+		weight += typeof element === 'string' ? Math.max(element.length, 1) : 1;
+	}
+	return weight;
+}
+
 /**
  * Hands off to the engine unless every element is a primitive. O(n) over a
  * receiver the size cap already limits, and runs before anything is
@@ -390,7 +411,10 @@ function evalCall(node: Extract<SimpleNode, { kind: 'call' }>, env: Env): unknow
 		if (STRINGIFIES_ELEMENTS.has(node.method)) assertPrimitiveElements(receiver);
 		if (node.method === 'concat') assertConcatWeight(receiver, args);
 	}
-	env.charge(preflightSize(receiver, node.method, args));
+	const size = preflightSize(receiver, node.method, args);
+	env.charge(
+		isArray(receiver) && COMPARES_ELEMENTS.has(node.method) ? comparisonWeight(receiver) : size,
+	);

 	return bounded(method.apply(receiver, args));
 }
