+		// An equal-length string argument is compared against each string
+		// element by content, so the comparing array methods are charged for the
+		// characters of their elements, not one unit per element.
+		test.each(['includes', 'indexOf', 'lastIndexOf'])(
+			'array %s is charged for the content of its elements',
+			(method) => {
+				const big = 'x'.repeat(MAX_RESULT_LENGTH / 2);
+				const probe = `${'x'.repeat(big.length - 1)}y`;
+				const visits = MAX_WORK / MAX_RESULT_LENGTH;
+				const expr = `{{ $json.many.some(n => $json.list.${method}(n) > 0) }}`;
+				expect(
+					nativeOn(expr, {
+						$json: { many: new Array<string>(visits).fill(probe), list: [big, big] },
+					}),
+				).toEqual({ handled: false });
+				expect(
+					nativeOn(expr, {
+						$json: { many: new Array<string>(visits).fill(probe), list: ['a', 'b'] },
+					}),
+				).toEqual({ handled: true, value: false });
+			},
+		);
